import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";

export function GithubAccount({
  login,
  authorizing,
  onChange,
}: {
  login: string;
  authorizing: boolean;
  onChange: () => void;
}) {
  const initial = login.slice(0, 1).toUpperCase();

  return (
    <div className="flex items-center justify-between gap-4 rounded-lg border border-border px-4 py-3">
      <div className="flex min-w-0 items-center gap-3">
        <Avatar size="lg">
          <AvatarImage
            src={`https://github.com/${encodeURIComponent(login)}.png`}
            alt=""
          />
          <AvatarFallback>{initial}</AvatarFallback>
        </Avatar>
        <div className="min-w-0">
          <p className="truncate text-sm font-semibold">{login}</p>
          <p className="mt-1 text-sm text-muted-foreground">GitHub connected</p>
        </div>
      </div>
      <Button
        type="button"
        variant="ghost"
        disabled={authorizing}
        onClick={onChange}
        className="cursor-pointer"
      >
        {authorizing ? "Waiting…" : "Change"}
      </Button>
    </div>
  );
}

import { GithubIcon } from "@/components/icons/github-icon";
import { Button } from "@/components/ui/button";

export function GithubConnectPrompt({
  authorizing,
  onConnect,
}: {
  authorizing: boolean;
  onConnect: () => void;
}) {
  return (
    <div className="grid gap-3">
      <Button
        type="button"
        variant="outline"
        className="h-14 w-full cursor-pointer justify-start px-4"
        disabled={authorizing}
        onClick={onConnect}
      >
        <GithubIcon />
        {authorizing ? "Waiting for GitHub…" : "Connect GitHub"}
      </Button>
      <p className="text-xs text-muted-foreground">Connect one repository.</p>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import type { GithubRepoOption, GithubSelection } from "@/lib/github/types";

export function GithubRepoSelect({
  repos,
  installationId,
  selection,
  onSelectionChange,
}: {
  repos: GithubRepoOption[];
  installationId: number;
  selection: GithubSelection | null;
  onSelectionChange: (value: GithubSelection) => void;
}) {
  const [query, setQuery] = useState("");
  const selected = repos.find((repo) => repo.fullName === selection?.fullName);
  const normalized = query.trim().toLowerCase();
  const visible = normalized
    ? repos.filter((repo) => repo.fullName.toLowerCase().includes(normalized))
    : repos;

  return (
    <div className="grid gap-2">
      <Label htmlFor="github-repo">Repository</Label>
      <Select
        value={selection?.fullName ?? null}
        onOpenChange={(open) => {
          if (!open) setQuery("");
        }}
        onValueChange={(value) => {
          if (!value) return;
          const repo = repos.find((item) => item.fullName === value);
          if (!repo) return;
          onSelectionChange({
            installationId,
            fullName: repo.fullName,
            defaultBranch: repo.defaultBranch,
            branch: repo.defaultBranch,
          });
        }}
      >
        <SelectTrigger id="github-repo" className="h-11 w-full">
          <SelectValue placeholder="Choose a repository">
            {selected
              ? repoLabel(selected.fullName, selected.private)
              : "Choose a repository"}
          </SelectValue>
        </SelectTrigger>
        <SelectContent
          header={
            <div className="sticky top-0 z-10 bg-popover p-1.5">
              <Input
                value={query}
                placeholder="Search repositories"
                aria-label="Search repositories"
                autoFocus
                onChange={(event) => setQuery(event.target.value)}
                onKeyDown={(event) => event.stopPropagation()}
              />
            </div>
          }
        >
          {visible.length === 0 ? (
            <p className="px-2 py-1.5 text-sm text-muted-foreground">
              No repositories
            </p>
          ) : (
            visible.map((repo) => (
              <SelectItem key={repo.id} value={repo.fullName}>
                {repoLabel(repo.fullName, repo.private)}
              </SelectItem>
            ))
          )}
        </SelectContent>
      </Select>
      <p className="text-xs text-muted-foreground">
        The agent opens pull requests in this repository.
      </p>
    </div>
  );
}

function repoLabel(fullName: string, isPrivate: boolean) {
  return isPrivate ? `${fullName} (private)` : fullName;
}

import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import type { GithubSelection } from "@/lib/github/types";

export function GithubBranchSelect({
  selection,
  branches,
  loading,
  onBranchChange,
}: {
  selection: GithubSelection;
  branches: string[];
  loading: boolean;
  onBranchChange: (branch: string) => void;
}) {
  const names = branches.includes(selection.branch)
    ? branches
    : [selection.branch, ...branches];

  return (
    <div className="grid gap-2">
      <Label htmlFor="github-branch">Branch</Label>
      <Select
        value={selection.branch}
        onValueChange={(branch) => {
          if (!branch) return;
          onBranchChange(branch);
        }}
      >
        <SelectTrigger id="github-branch" className="h-11 w-full">
          <SelectValue placeholder="Choose a branch">
            {selection.branch}
          </SelectValue>
        </SelectTrigger>
        <SelectContent>
          {names.map((branch) => (
            <SelectItem key={branch} value={branch}>
              {branch}
              {branch === selection.defaultBranch ? " · default" : ""}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      <p className="text-xs text-muted-foreground">
        {loading
          ? "Loading branches…"
          : "Pull requests open against this branch."}
      </p>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { GithubIcon } from "@/components/icons/github-icon";
import { Button } from "@/components/ui/button";
import { GithubAccount } from "@/components/onboarding/steps/github/github-account";
import { GithubBranchSelect } from "@/components/onboarding/steps/github/github-branch-select";
import { GithubConnectPrompt } from "@/components/onboarding/steps/github/github-connect-prompt";
import { GithubRepoSelect } from "@/components/onboarding/steps/github/github-repo-select";
import {
  GITHUB_INSTALL_MESSAGE,
  type GithubConnection,
  type GithubInstallMessage,
  type GithubSelection,
} from "@/lib/github/types";

export function GithubStep({
  selection,
  onSelectionChange,
}: {
  selection: GithubSelection | null;
  onSelectionChange: (value: GithubSelection | null) => void;
}) {
  const [connection, setConnection] = useState<GithubConnection | null>(null);
  const [loading, setLoading] = useState(true);
  const [authorizing, setAuthorizing] = useState(false);
  const [error, setError] = useState("");
  const [refreshKey, setRefreshKey] = useState(0);
  const selectionRef = useRef(selection);
  selectionRef.current = selection;

  const selectedRepo = selection?.fullName ?? "";
  const [branchLoad, setBranchLoad] = useState<{
    repo: string;
    branches: string[];
    loading: boolean;
  }>({ repo: "", branches: [], loading: false });

  if (branchLoad.repo !== selectedRepo) {
    setBranchLoad({
      repo: selectedRepo,
      branches: [],
      loading: selectedRepo.length > 0,
    });
  }

  useEffect(() => {
    let cancelled = false;

    readJson<GithubConnection>("/api/github/connection")
      .then((next) => {
        if (cancelled) return;
        setConnection(next);
        setLoading(false);
        reconcileSelection(next, selectionRef.current, onSelectionChange);
      })
      .catch((loadError) => {
        if (cancelled) return;
        setConnection({ connected: false });
        setError(messageFrom(loadError));
        setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [onSelectionChange, refreshKey]);

  useEffect(() => {
    if (!selectedRepo) return;

    let cancelled = false;

    readJson<{ branches: string[] }>(
      `/api/github/branches?repo=${encodeURIComponent(selectedRepo)}`,
    )
      .then((body) => {
        if (cancelled) return;
        setBranchLoad({
          repo: selectedRepo,
          branches: body.branches,
          loading: false,
        });
      })
      .catch((branchError) => {
        if (cancelled) return;
        setBranchLoad({ repo: selectedRepo, branches: [], loading: false });
        setError(messageFrom(branchError));
      });

    return () => {
      cancelled = true;
    };
  }, [selectedRepo]);

  function connect() {
    setError("");
    const popup = window.open(
      "/api/github/install",
      "friction-fixer-github",
      "popup,width=980,height=760",
    );

    if (!popup) {
      const destination = new URL("/api/github/install", window.location.href);
      window.location.assign(destination.href);
      return;
    }

    setAuthorizing(true);

    const onMessage = (event: MessageEvent) => {
      if (event.origin !== window.location.origin) return;
      if (event.source !== popup) return;
      if (!isInstallMessage(event.data)) return;
      cleanup();
      if (event.data.error) {
        setError(event.data.error);
        return;
      }
      onSelectionChange(null);
      setConnection(null);
      setLoading(true);
      setRefreshKey((value) => value + 1);
    };

    const timer = window.setInterval(() => {
      if (popup.closed) cleanup();
    }, 400);

    function cleanup() {
      window.clearInterval(timer);
      window.removeEventListener("message", onMessage);
      setAuthorizing(false);
    }

    window.addEventListener("message", onMessage);
  }

  const repos = connection?.connected ? connection.repos : [];
  const branches =
    branchLoad.repo === selectedRepo ? branchLoad.branches : [];
  const branchesLoading =
    branchLoad.repo === selectedRepo ? branchLoad.loading : false;

  return (
    <div className="grid gap-6">
      {loading && !connection?.connected ? (
        <p className="text-sm text-muted-foreground">Checking GitHub…</p>
      ) : null}

      {connection?.connected ? (
        <div className="grid gap-5">
          <GithubAccount
            login={connection.accountLogin}
            authorizing={authorizing}
            onChange={connect}
          />

          {repos.length === 0 ? (
            <div className="grid gap-3">
              <p className="text-sm text-muted-foreground">
                This install cannot see a repository yet. Choose one on GitHub,
                then come back.
              </p>
              <Button type="button" variant="outline" onClick={connect}>
                <GithubIcon />
                Choose a repository
              </Button>
            </div>
          ) : (
            <>
              <GithubRepoSelect
                repos={repos}
                installationId={connection.installationId}
                selection={selection}
                onSelectionChange={onSelectionChange}
              />
              {selection ? (
                <GithubBranchSelect
                  selection={selection}
                  branches={branches}
                  loading={branchesLoading}
                  onBranchChange={(branch) =>
                    onSelectionChange({ ...selection, branch })
                  }
                />
              ) : null}
            </>
          )}
        </div>
      ) : loading ? null : (
        <GithubConnectPrompt authorizing={authorizing} onConnect={connect} />
      )}

      {error ? (
        <p
          className="rounded-md bg-destructive/10 px-3 py-2 text-sm text-destructive"
          role="alert"
        >
          {error}
        </p>
      ) : null}
    </div>
  );
}

function reconcileSelection(
  connection: GithubConnection,
  selection: GithubSelection | null,
  onSelectionChange: (value: GithubSelection | null) => void,
) {
  if (!connection.connected) return;

  const match = selection
    ? connection.repos.find((repo) => repo.fullName === selection.fullName)
    : undefined;

  if (selection && !match) {
    onSelectionChange(null);
    return;
  }

  if (
    selection &&
    match &&
    selection.installationId !== connection.installationId
  ) {
    onSelectionChange({
      ...selection,
      installationId: connection.installationId,
      defaultBranch: match.defaultBranch,
    });
    return;
  }

  if (!selection && connection.repos.length === 1) {
    const repo = connection.repos[0];
    onSelectionChange({
      installationId: connection.installationId,
      fullName: repo.fullName,
      defaultBranch: repo.defaultBranch,
      branch: repo.defaultBranch,
    });
  }
}

function isInstallMessage(value: unknown): value is GithubInstallMessage {
  return (
    typeof value === "object" &&
    value !== null &&
    "type" in value &&
    value.type === GITHUB_INSTALL_MESSAGE
  );
}

async function readJson<T>(path: string): Promise<T> {
  const response = await fetch(path, { cache: "no-store" });
  const body = (await response.json().catch(() => ({}))) as {
    error?: string;
  } & T;
  if (!response.ok) {
    throw new Error(body.error || "Could not reach GitHub.");
  }
  return body;
}

function messageFrom(error: unknown) {
  return error instanceof Error ? error.message : "Could not reach GitHub.";
}
